def detect_and_read(path):
    # Try common encodings
    encodings = ["utf-8-sig", "utf-8", "cp1252", "latin1"]
    b = open(path, "rb").read()
    for enc in encodings:
        try:
            text = b.decode(enc)
            return enc, text
        except Exception:
            continue

